    10→use alloy_primitives::B256;
    11→use revm::{context::Block, context_interface::result::ResultAndState};
    12→
    13→/// Applies the pre-block call to the [EIP-4788] beacon block root contract, using the given block,
    14→/// chain spec, EVM.
    15→///
    16→/// Note: this does not commit the state changes to the database, it only transact the call.
    17→///
    18→/// Returns `None` if Cancun is not active or the block is the genesis block, otherwise returns the
    19→/// result of the call.
    20→///
    21→/// [EIP-4788]: https://eips.ethereum.org/EIPS/eip-4788
    22→#[inline]
    23→pub(crate) fn transact_beacon_root_contract_call<Halt>(
    24→    spec: impl EthereumHardforks,
    25→    parent_beacon_block_root: Option<B256>,
    26→    evm: &mut impl Evm<HaltReason = Halt>,
    27→) -> Result<Option<ResultAndState<Halt>>, BlockExecutionError> {
    28→    if !spec.is_cancun_active_at_timestamp(evm.block().timestamp().saturating_to()) {
    29→        return Ok(None);
    30→    }
    31→
    32→    let parent_beacon_block_root =
    33→        parent_beacon_block_root.ok_or(BlockValidationError::MissingParentBeaconBlockRoot)?;
    34→
    35→    // if the block number is zero (genesis block) then the parent beacon block root must
    36→    // be 0x0 and no system transaction may occur as per EIP-4788
    37→    if evm.block().number().is_zero() {
    38→        if !parent_beacon_block_root.is_zero() {
    39→            return Err(BlockValidationError::CancunGenesisParentBeaconBlockRootNotZero {
    40→                parent_beacon_block_root,
    41→            }
    42→            .into());
    43→        }
    44→        return Ok(None);
    45→    }
    46→
    47→    let res = match evm.transact_system_call(
    48→        alloy_eips::eip4788::SYSTEM_ADDRESS,
    49→        BEACON_ROOTS_ADDRESS,
    50→        parent_beacon_block_root.0.into(),
    51→    ) {
